import { test, before } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { setWallet, houseCall, sendHouseCall, signerBlocker, CALL_AS_TGAS } from '../../../app/src/house-sign.js';
import { sha256Hex } from '../../../app/src/sha256.js';
import * as W from '../../../shared/vault/tx.js';

// The wallet bundle is generated by app/build.mjs, so the executor takes it by injection.
// The node tests use the same functions the bundle re-exports.
before(() => setWallet(W));

const read = p => readFileSync(new URL('../../../' + p, import.meta.url), 'utf8');
const rowFor = key => ({
  agent: W.pubkeyHex(key), nonce: '4', epoch: '0',
  min_amount: '1000000000000000000000', per_action_cap: '5000000000000000000000',
});
const ctxFor = (key, extra = {}) => ({
  account: 'alice.near', board: 'board.nearcarta.near', house: 'house.nearcarta.near',
  row: rowFor(key), tokenId: 'alice.near', ...extra,
});
const okRpc = () => { const seen = []; const rpc = async (m, p) => { seen.push(p); return { result: { status: { SuccessValue: '' }, transaction: { hash: 'h' } } }; }; rpc.seen = seen; return rpc; };

test('the CTA and the AI sign through the board, never the house account', () => {
  const key = W.keyFrom();
  const build = houseCall({ kind: 'checkin', ctx: ctxFor(key) });
  assert.equal(build.method, 'propose_call_as');
  assert.equal(build.args.receiver, 'house.nearcarta.near');
  assert.equal(build.args.method, 'house_session_check_in');
  assert.equal(build.args.hold, false);
  // The signed text is what carries row_owner; the board rewrites it on chain.
  assert.match(build.message, /^board-call-as-v1\|mainnet\|board\.nearcarta\.near\|2\|alice\.near\|house\.nearcarta\.near\|house_session_check_in\|[0-9a-f]{64}\|/);
  assert.equal(JSON.parse(build.args.args).row_owner, 'alice.near');
});

test('all four writes exist: mint, check-in, set-line and pay', () => {
  const key = W.keyFrom();
  const base = ctxFor(key);
  assert.equal(houseCall({ kind: 'mint', ctx: base }).args.method, 'house_session_mint');
  assert.equal(houseCall({ kind: 'checkin', ctx: base }).args.method, 'house_session_check_in');
  const line = houseCall({ kind: 'setline', ctx: base, params: { heirs: ['heir.near'], guardians: ['g1.near'], threshold: 1, periodNs: 60000000000, waitNs: 60000000000 } });
  assert.equal(line.args.method, 'house_session_set_line');
  assert.deepEqual(JSON.parse(line.args.args).heirs, ['heir.near']);
  const pay = houseCall({ kind: 'pay', ctx: base, params: { receiver: 'bob.near', amount: '1000' } });
  assert.equal(pay.args.method, 'house_session_pay');
  assert.equal(JSON.parse(pay.args.args).receiver_id, 'bob.near');
});

test('a signed house call leaves the browser and names the session key as signer', async () => {
  // setWallet is process-global, so this test sets it right before it signs.
  setWallet(W);
  const key = W.keyFrom();
  const rpc = okRpc();
  const build = houseCall({ kind: 'checkin', ctx: ctxFor(key) });
  const out = await sendHouseCall({ rpc, key, accessKey: { nonce: 7, block_hash: '11111111111111111111111111111111' }, me: 'alice.near', board: 'board.nearcarta.near', build });
  assert.equal(out.ok, true);
  assert.equal(out.signer, 'agent');
  assert.equal(out.tx.length, 44);
  assert.equal(rpc.seen.length, 1);
  assert.equal(typeof rpc.seen[0].signed_tx_base64, 'string');
  assert.equal(rpc.seen[0].wait_until, 'FINAL');
  // A function-call key cannot attach NEAR: the gas is prepaid, the deposit stays in the row.
  assert.ok(CALL_AS_TGAS >= 100n);
});

test('a missing key, a foreign agent key, a stale key and a short allowance all refuse before signing', () => {
  const key = W.keyFrom();
  const row = rowFor(key);
  const board = 'board.nearcarta.near';
  const ak = (over = {}) => ({ permission: { FunctionCall: { receiver_id: board, method_names: [], allowance: '999999999999999999999999', ...over } } });
  assert.match(signerBlocker({ key: null, row, board }), /Set up your agent/);
  assert.match(signerBlocker({ key, row: { ...row, agent: 'cd'.repeat(32) }, board, accessKey: ak() }), /not the agent on the row/);
  assert.match(signerBlocker({ key, row, board, accessKey: null }), /session key was not found/);
  assert.match(signerBlocker({ key, row, board, accessKey: ak({ receiver_id: 'other.near' }) }), /not for the board/);
  assert.match(signerBlocker({ key, row, board, accessKey: ak({ method_names: ['propose'] }) }), /cannot call propose_call_as/);
  assert.match(signerBlocker({ key, row, board, accessKey: ak({ allowance: '1' }) }), /allowance cannot buy/);
  assert.equal(signerBlocker({ key, row, board, accessKey: ak({ method_names: ['propose_call_as'] }) }), '');
});

test('the deposit comes from the row, and bitcoin with a value is refused', () => {
  const key = W.keyFrom();
  // A rule with no minimum still needs 1 yocto.
  const zero = houseCall({ kind: 'checkin', ctx: ctxFor(key, { row: { ...rowFor(key), min_amount: '0' } }) });
  assert.equal(zero.args.deposit, '1');
  const min = houseCall({ kind: 'checkin', ctx: ctxFor(key) });
  assert.equal(min.args.deposit, '1000000000000000000000');
  assert.throws(() => houseCall({ kind: 'prepare', ctx: ctxFor(key), params: { chain: 'btc', asset: 'BTC', to: 'bc1qexample', value: '1' } }), /signing only/);
  const btc = houseCall({ kind: 'prepare', ctx: ctxFor(key), params: { chain: 'btc', asset: 'BTC', to: 'bc1qexample', value: '0' } });
  assert.equal(btc.args.hold, true);
});

test('the room and the agent both reach the executor, and neither signs on import', () => {
  const room = read('app/src/panels/house-room.js');
  assert.match(room, /sign: \(build, kind\) => signAndSend\(build, kind\)/);
  assert.match(room, /sendHouseCall/);
  const agent = read('app/src/panels/house-agent.js');
  assert.match(agent, /if \(ctx\.sign && plan\.write\)/);
  assert.match(agent, /label: 'live', signed: true, live: true, tx: sent\.tx/);
  // The old copy claimed nothing could sign; it must be gone from the live path.
  assert.doesNotMatch(agent, /Live broadcast is blocked\. Nothing was signed\.'\s*;/);
});

test('the house envelope hashes with the shipped sha256', () => {
  const args = '{"token_id":"alice.near"}';
  assert.equal(sha256Hex(args), createHash('sha256').update(args).digest('hex'));
});

test('the CTA and the AI produce the same signed call for the same intent', async () => {
  const { planHouseLine, runHouseTurn } = await import('../../../app/src/panels/house-agent.js');
  const key = W.keyFrom();
  const ctx = {
    account: 'alice.near', board: 'board.nearcarta.near', house: 'house.nearcarta.near', tokenId: '',
    row: { nonce: '4', epoch: '0', min_amount: '1000000000000000000000', per_action_cap: '5000000000000000000000', balance: '50000000000000000000000', receivers: ['house.nearcarta.near'] },
  };
  // The CTA reads sentence(); the dock passes typed text. Both reach the same plan.
  const plan = planHouseLine('Mint my deed', ctx);
  assert.equal(plan.action, 'mint');
  assert.equal(plan.write, 'mint');
  const seen = [];
  const out = await runHouseTurn('Mint my deed', { ...ctx, sign: async (build, kind) => { seen.push([build.method, build.args.method, kind]); return { ok: true, tx: 'SAME' }; } });
  assert.equal(out.label, 'live');
  assert.equal(out.tx, 'SAME');
  assert.deepEqual(seen[0], ['propose_call_as', 'house_session_mint', 'mint']);
});
